stereotypeDefinition.displayFunction:
const globItems = (properties["Glob"].value || "")
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(line => line.length > 0);

const classificationIds = JSON.parse(properties["Classification"].value || "[]");
const classificationNames = classificationIds
    .map(id => lookup(id)?.getName())
    .filter(name => !!name);

const parts = [
    ...globItems,
    properties["Severity"].value,
    ...classificationNames
].filter(part => !!part);

return parts.join(", ");
